    31→/**
    32→ * Gas Calculator for Osaka
    33→ *
    34→ * <UL>
    35→ *   <LI>TBD
    36→ * </UL>
    37→ */
    38→public class OsakaGasCalculator extends PragueGasCalculator {
    39→  /** constant indicating the maximum integer value for L1 precompile addresses (0xFF) */
    40→  public static final int MAX_L1_PRECOMPILE = 255;
    41→
    42→  /** configured maximum l2 precompile address value for this fork / gas calculator. */
    43→  protected int maxL2Precompile;
    44→
    45→  /** Instantiates a new Osaka Gas Calculator. */
    46→  public OsakaGasCalculator() {
    47→    this(BLS12_MAP_FP2_TO_G2.getInt(16), P256_VERIFY.getInt(16));
    48→  }
    49→
    50→  /**
    51→   * Instantiates a new Osaka Gas Calculator
    52→   *
    53→   * @param maxPrecompile the max precompile address from the L1 precompile range (0x01 - 0xFF)
    54→   * @param maxL2Precompile max precompile address from the L2 precompile space (0x0100 - 0x01FF)
    55→   */
    56→  protected OsakaGasCalculator(final int maxPrecompile, final int maxL2Precompile) {
    57→    super(maxPrecompile);
    58→    this.maxL2Precompile = maxL2Precompile;
    59→  }
    60→
    61→  /**
    62→   * Instantiates a new Osaka Gas Calculator, uses default P256_VERIFY as max L2 precompile.
    63→   *
    64→   * @param maxPrecompile the max precompile address from the L1 precompile range (0x01 - 0xFF)
    65→   */
    66→  protected OsakaGasCalculator(final int maxPrecompile) {
    67→    this(maxPrecompile, P256_VERIFY.getInt(16));
    68→  }
    69→
    70→  @Override
    71→  public boolean isPrecompile(final Address address) {
    72→    final byte[] addressBytes = address.toArrayUnsafe();
    73→
    74→    // First 18 bytes must be zero:
    75→    for (int i = 0; i < 18; i++) {
    76→      if (addressBytes[i] != 0) {
    77→        return false;
    78→      }
    79→    }
    80→    // Interpret last two bytes as big-endian unsigned short.
    81→    final int precompileValue = address.getInt(16);
    82→
    83→    // values in range [1, 0x01FF] inclusive to include L1 and L2 precompiles,
    84→    // assert max precompile in each range:
    85→    return (precompileValue > 0)
    86→        && ((precompileValue <= MAX_L1_PRECOMPILE)
    87→            ? precompileValue <= this.maxPrecompile
    88→            : precompileValue <= maxL2Precompile);
    89→  }
    90→
    91→  @Override
    92→  public long modExpGasCost(final Bytes input) {
    93→    final long baseLength = BigIntegerModularExponentiationPrecompiledContract.baseLength(input);
    94→    final long exponentLength =
    95→        BigIntegerModularExponentiationPrecompiledContract.exponentLength(input);
    96→    final long modulusLength =
    97→        BigIntegerModularExponentiationPrecompiledContract.modulusLength(input);
    98→    final long exponentOffset =
    99→        clampedAdd(BigIntegerModularExponentiationPrecompiledContract.BASE_OFFSET, baseLength);
   100→
   101→    final long maxLength = Math.max(modulusLength, baseLength);
   102→    long multiplicationComplexity = 16;
   103→    long words = (maxLength + 7L) / 8L;
   104→    words = Words.clampedMultiply(words, words);
   105→    if (maxLength > 32) {
   106→      multiplicationComplexity = words * 2;
   107→    }
   108→
   109→    final long firstExponentBytesCap =
   110→        Math.min(exponentLength, ByzantiumGasCalculator.MAX_FIRST_EXPONENT_BYTES);
   111→    final BigInteger firstExpBytes =
   112→        BigIntegerModularExponentiationPrecompiledContract.extractParameter(
   113→            input, clampedToInt(exponentOffset), clampedToInt(firstExponentBytesCap));
   114→    final long adjustedExponentLength = adjustedExponentLength(exponentLength, firstExpBytes);
   115→
   116→    long gasRequirement =
   117→        clampedMultiply(multiplicationComplexity, Math.max(adjustedExponentLength, 1L));
   118→
   119→    return Math.max(gasRequirement, 500L);
   120→  }
   121→
   122→  /**
   123→   * Adjusted exponent length.
   124→   *
   125→   * @param exponentLength the exponent length
   126→   * @param firstExpBytes the first exp bytes
   127→   * @return the long
   128→   */
   129→  public static long adjustedExponentLength(
   130→      final long exponentLength, final BigInteger firstExpBytes) {
   131→    final int bitLength = bitLength(firstExpBytes);
   132→    if (exponentLength <= WORD_SIZE) {
   133→      return bitLength;
   134→    } else {
   135→      return clampedAdd(clampedMultiply(16, (exponentLength - WORD_SIZE)), bitLength);
   136→    }
   137→  }
   138→}
