    37→public class TrieNodeDecoder {
    38→  private static final StoredNodeFactory<Bytes> emptyNodeFactory =
    39→      new StoredNodeFactory<>((l, h) -> Optional.empty(), Function.identity(), Function.identity());
    40→
    41→  // Hide constructor for static utility class
    42→  private TrieNodeDecoder() {}
    43→
    44→  /**
    45→   * Decode an rlp-encoded trie node
    46→   *
    47→   * @param location The location in the trie.
    48→   * @param rlp The rlp-encoded node
    49→   * @return A {@code Node} representation of the rlp data
    50→   */
    51→  public static Node<Bytes> decode(final Bytes location, final Bytes rlp) {
    52→    return emptyNodeFactory.decode(location, rlp);
    53→  }
    54→
    55→  /**
    56→   * Flattens this node and all of its inlined nodes and node references into a list.
    57→   *
    58→   * @param location The location in the trie.
    59→   * @param nodeRlp The bytes of the trie node to be decoded.
    60→   * @return A list of nodes and node references embedded in the given rlp.
    61→   */
    62→  public static List<Node<Bytes>> decodeNodes(final Bytes location, final Bytes nodeRlp) {
    63→    if (nodeRlp.equals(MerkleTrie.EMPTY_TRIE_NODE)) {
    64→      return new ArrayList<>();
    65→    }
    66→    final Node<Bytes> node = decode(location, nodeRlp);
    67→    final List<Node<Bytes>> nodes = new ArrayList<>();
    68→    nodes.add(node);
    69→
    70→    final List<Node<Bytes>> toProcess = new ArrayList<>(node.getChildren());
    71→    while (!toProcess.isEmpty()) {
    72→      final Node<Bytes> currentNode = toProcess.remove(0);
    73→      if (Objects.equals(NullNode.instance(), currentNode)) {
    74→        // Skip null nodes
    75→        continue;
    76→      }
    77→      nodes.add(currentNode);
    78→
    79→      if (!currentNode.isReferencedByHash()) {
    80→        // If current node is inlined, that means we can process its children
    81→        toProcess.addAll(currentNode.getChildren());
    82→      }
    83→    }
    84→
    85→    return nodes;
    86→  }
    87→
    88→  /**
    89→   * Walks the trie in a bread-first manner, returning the list of nodes encountered in order. If
    90→   * any nodes are missing from the nodeLoader, those nodes are just skipped.
    91→   *
    92→   * @param nodeLoader The NodeLoader for looking up nodes by hash
    93→   * @param rootHash The hash of the root node
    94→   * @param maxDepth The maximum depth to traverse to. A value of zero will traverse the root node
    95→   *     only.
    96→   * @return A stream non-null nodes in the breadth-first traversal order.
    97→   */
    98→  public static Stream<Node<Bytes>> breadthFirstDecoder(
    99→      final NodeLoader nodeLoader, final Bytes32 rootHash, final int maxDepth) {
   100→    checkArgument(maxDepth >= 0);
   101→    return Streams.stream(new BreadthFirstIterator(nodeLoader, rootHash, maxDepth));
   102→  }
   103→
   104→  /**
   105→   * Walks the trie in a bread-first manner, returning the list of nodes encountered in order. If
   106→   * any nodes are missing from the nodeLoader, those nodes are just skipped.
   107→   *
   108→   * @param nodeLoader The NodeLoader for looking up nodes by hash
   109→   * @param rootHash The hash of the root node
   110→   * @return A stream non-null nodes in the breadth-first traversal order.
   111→   */
   112→  public static Stream<Node<Bytes>> breadthFirstDecoder(
   113→      final NodeLoader nodeLoader, final Bytes32 rootHash) {
   114→    return breadthFirstDecoder(nodeLoader, rootHash, Integer.MAX_VALUE);
   115→  }
   116→
   117→  private static class BreadthFirstIterator implements Iterator<Node<Bytes>> {
   118→
   119→    private final int maxDepth;
   120→    private final StoredNodeFactory<Bytes> nodeFactory;
   121→
   122→    private int currentDepth = 0;
   123→    private final List<Node<Bytes>> currentNodes = new ArrayList<>();
   124→    private final List<Node<Bytes>> nextNodes = new ArrayList<>();
   125→
   126→    BreadthFirstIterator(final NodeLoader nodeLoader, final Bytes32 rootHash, final int maxDepth) {
   127→      this.maxDepth = maxDepth;
   128→      this.nodeFactory =
   129→          new StoredNodeFactory<>(nodeLoader, Function.identity(), Function.identity());
   130→
   131→      nodeLoader
   132→          .getNode(Bytes.EMPTY, rootHash)
   133→          .map(h -> TrieNodeDecoder.decode(Bytes.EMPTY, h))
   134→          .ifPresent(currentNodes::add);
   135→    }
   136→
   137→    @Override
   138→    public boolean hasNext() {
   139→      return !currentNodes.isEmpty() && currentDepth <= maxDepth;
   140→    }
   141→
   142→    @Override
   143→    public Node<Bytes> next() {
   144→      if (!hasNext()) {
   145→        throw new NoSuchElementException();
   146→      }
   147→
   148→      final Node<Bytes> nextNode = currentNodes.remove(0);
   149→
   150→      final List<Node<Bytes>> children = new ArrayList<>(nextNode.getChildren());
   151→      while (!children.isEmpty()) {
   152→        Node<Bytes> child = children.remove(0);
   153→        if (Objects.equals(child, NullNode.instance())) {
   154→          // Ignore null nodes
   155→          continue;
   156→        }
   157→        if (child.isReferencedByHash()) {
   158→          // Retrieve hash-referenced child
   159→          final Optional<Node<Bytes>> maybeChildNode = nodeFactory.retrieve(null, child.getHash());
   160→          if (maybeChildNode.isEmpty()) {
   161→            continue;
   162→          }
   163→          child = maybeChildNode.get();
   164→        }
   165→        nextNodes.add(child);
   166→      }
   167→
   168→      // Set up next level
   169→      if (currentNodes.isEmpty()) {
   170→        currentDepth += 1;
   171→        currentNodes.addAll(nextNodes);
   172→        nextNodes.clear();
   173→      }
   174→
   175→      return nextNode;
   176→    }
   177→  }
   178→}
