    25→public class PutVisitor<V> implements PathNodeVisitor<V> {
    26→  private final NodeFactory<V> nodeFactory;
    27→  private final V value;
    28→
    29→  public PutVisitor(final NodeFactory<V> nodeFactory, final V value) {
