    37→    final int commonPathLength = extensionPath.commonPrefixLength(path);
    38→    assert commonPathLength < path.size()
    39→        : "Visiting path doesn't end with a non-matching terminator";
    40→
    41→    if (commonPathLength == extensionPath.size()) {
    42→      final Node<V> newChild = extensionNode.getChild().accept(this, path.slice(commonPathLength));
    43→      return extensionNode.replaceChild(newChild);
    44→    }
    45→
    46→    // path diverges before the end of the extension - create a new branch
    47→
    48→    final byte leafIndex = path.get(commonPathLength);
    49→    final Bytes leafPath = path.slice(commonPathLength + 1);
    50→
    51→    final byte extensionIndex = extensionPath.get(commonPathLength);
    52→    final Node<V> updatedExtension =
    53→        extensionNode.replacePath(extensionPath.slice(commonPathLength + 1));
    54→    final Node<V> leaf = nodeFactory.createLeaf(leafPath, value);
    55→    final Node<V> branch =
    56→        nodeFactory.createBranch(leafIndex, leaf, extensionIndex, updatedExtension);
    57→
    58→    if (commonPathLength > 0) {
    59→      return nodeFactory.createExtension(extensionPath.slice(0, commonPathLength), branch);
    60→    } else {
    61→      return branch;
    62→    }
    63→  }
    64→
    65→  @Override
    66→  public Node<V> visit(final BranchNode<V> branchNode, final Bytes path) {
    67→    assert path.size() > 0 : "Visiting path doesn't end with a non-matching terminator";
    68→
    69→    final byte childIndex = path.get(0);
    70→    if (childIndex == CompactEncoding.LEAF_TERMINATOR) {
    71→      return branchNode.replaceValue(value);
    72→    }
    73→
    74→    final Node<V> updatedChild = branchNode.child(childIndex).accept(this, path.slice(1));
    75→    return branchNode.replaceChild(childIndex, updatedChild);
    76→  }
