    15→package org.hyperledger.besu.ethereum.trie.patricia;
    16→
    17→import org.hyperledger.besu.ethereum.trie.CompactEncoding;
    18→import org.hyperledger.besu.ethereum.trie.Node;
    19→import org.hyperledger.besu.ethereum.trie.NullNode;
    20→import org.hyperledger.besu.ethereum.trie.PathNodeVisitor;
    21→
    22→import org.apache.tuweni.bytes.Bytes;
    23→
    24→public class GetVisitor<V> implements PathNodeVisitor<V> {
    25→  private final Node<V> NULL_NODE_RESULT = NullNode.instance();
    26→
    27→  @Override
    28→  public Node<V> visit(final ExtensionNode<V> extensionNode, final Bytes path) {
    29→    final Bytes extensionPath = extensionNode.getPath();
    30→    final int commonPathLength = extensionPath.commonPrefixLength(path);
    31→    assert commonPathLength < path.size()
    32→        : "Visiting path doesn't end with a non-matching terminator";
    33→
    34→    if (commonPathLength < extensionPath.size()) {
    35→      // path diverges before the end of the extension, so it cannot match
    36→      return NULL_NODE_RESULT;
    37→    }
    38→
    39→    return extensionNode.getChild().accept(this, path.slice(commonPathLength));
    40→  }
    41→
    42→  @Override
    43→  public Node<V> visit(final BranchNode<V> branchNode, final Bytes path) {
    44→    assert path.size() > 0 : "Visiting path doesn't end with a non-matching terminator";
    45→
    46→    final byte childIndex = path.get(0);
    47→    if (childIndex == CompactEncoding.LEAF_TERMINATOR) {
    48→      return branchNode;
    49→    }
    50→
    51→    return branchNode.child(childIndex).accept(this, path.slice(1));
    52→  }
    53→
    54→  @Override
    55→  public Node<V> visit(final LeafNode<V> leafNode, final Bytes path) {
    56→    final Bytes leafPath = leafNode.getPath();
    57→    if (leafPath.commonPrefixLength(path) != leafPath.size()) {
    58→      return NULL_NODE_RESULT;
    59→    }
    60→    return leafNode;
    61→  }
    62→
    63→  @Override
    64→  public Node<V> visit(final NullNode<V> nullNode, final Bytes path) {
    65→    return NULL_NODE_RESULT;
    66→  }
    67→}
