    41→/**
    42→ * The MainnetBlockValidator class implements the BlockValidator interface for the Mainnet Ethereum
    43→ * network. It validates and processes blocks according to the rules of the Mainnet Ethereum
    44→ * network.
    45→ */
    46→public class MainnetBlockValidator implements BlockValidator {
    47→
    48→  private static final Logger LOG = LoggerFactory.getLogger(MainnetBlockValidator.class);
    49→
    50→  /** The BlockHeaderValidator used to validate block headers. */
    51→  protected final BlockHeaderValidator blockHeaderValidator;
    52→
    53→  /** The BlockBodyValidator used to validate block bodies. */
    54→  protected final BlockBodyValidator blockBodyValidator;
    55→
    56→  /** The BlockProcessor used to process blocks. */
    57→  protected final BlockProcessor blockProcessor;
    58→
    59→  /** The maximum size of a block in RLP encoding. */
    60→  private final int maxRlpBlockSize;
    61→
    62→  /**
    63→   * Constructs a new MainnetBlockValidator with the given BlockHeaderValidator, BlockBodyValidator,
    64→   * BlockProcessor, and maximum RLP block size.
    65→   *
    66→   * @param blockHeaderValidator the BlockHeaderValidator used to validate block headers
    67→   * @param blockBodyValidator the BlockBodyValidator used to validate block bodies
    68→   * @param blockProcessor the BlockProcessor used to process blocks
    69→   * @param maxRlpBlockSize the maximum size of a block in RLP encoding
    70→   */
    71→  protected MainnetBlockValidator(
    72→      final BlockHeaderValidator blockHeaderValidator,
    73→      final BlockBodyValidator blockBodyValidator,
    74→      final BlockProcessor blockProcessor,
    75→      final int maxRlpBlockSize) {
    76→    this.blockHeaderValidator = blockHeaderValidator;
    77→    this.blockBodyValidator = blockBodyValidator;
    78→    this.blockProcessor = blockProcessor;
    79→    this.maxRlpBlockSize = maxRlpBlockSize;
    80→  }
    81→
    82→  /**
    83→   * Performs a full validation and processing of a block
    84→   *
    85→   * @param context the {@link ProtocolContext}
    86→   * @param block the block being validated and processed
    87→   * @param headerValidationMode the {@link HeaderValidationMode} used for validating the header
    88→   * @param ommerValidationMode the {@link HeaderValidationMode} used for validating the ommers
    89→   * @return an optional containing the {@link BlockProcessingOutputs} with the output of processing
    90→   *     the block, empty if the block was deemed invalid or couldn't be processed
    91→   */
    92→  @Override
    93→  public BlockProcessingResult validateAndProcessBlock(
    94→      final ProtocolContext context,
    95→      final Block block,
    96→      final HeaderValidationMode headerValidationMode,
    97→      final HeaderValidationMode ommerValidationMode) {
    98→    return validateAndProcessBlock(
    99→        context, block, headerValidationMode, ommerValidationMode, true, true);
   100→  }
   101→
   102→  @Override
   103→  public BlockProcessingResult validateAndProcessBlock(
   104→      final ProtocolContext context,
   105→      final Block block,
   106→      final HeaderValidationMode headerValidationMode,
   107→      final HeaderValidationMode ommerValidationMode,
   108→      final boolean shouldPersist) {
   109→    return validateAndProcessBlock(
   110→        context, block, headerValidationMode, ommerValidationMode, shouldPersist, true);
   111→  }
   112→
   113→  @Override
   114→  public BlockProcessingResult validateAndProcessBlock(
   115→      final ProtocolContext context,
   116→      final Block block,
   117→      final HeaderValidationMode headerValidationMode,
   118→      final HeaderValidationMode ommerValidationMode,
   119→      final boolean shouldUpdateHead,
   120→      final boolean shouldRecordBadBlock) {
   121→
   122→    final int blockSize = block.getSize();
   123→    if (blockSize > maxRlpBlockSize) {
   124→      final String errorMessage =
   125→          "Block size of " + blockSize + " bytes exceeds limit of " + maxRlpBlockSize + " bytes";
   126→      var retval = new BlockProcessingResult(errorMessage);
   127→      handleFailedBlockProcessing(block, retval, true, context);
   128→      return retval;
   129→    }
   130→
   131→    final BlockHeader header = block.getHeader();
   132→    final BlockHeader parentHeader;
   133→
   134→    try {
   135→      final MutableBlockchain blockchain = context.getBlockchain();
   136→      final Optional<BlockHeader> maybeParentHeader =
   137→          blockchain.getBlockHeader(header.getParentHash());
   138→      if (maybeParentHeader.isEmpty()) {
   139→        var retval =
   140→            new BlockProcessingResult(
   141→                "Parent block with hash " + header.getParentHash() + " not present");
   142→        // Blocks should not be marked bad due to missing data
   143→        handleFailedBlockProcessing(block, retval, false, context);
   144→        return retval;
   145→      }
   146→      parentHeader = maybeParentHeader.get();
   147→
   148→      if (!blockHeaderValidator.validateHeader(
   149→          header, parentHeader, context, headerValidationMode)) {
   150→        final String error = String.format("Header validation failed (%s)", headerValidationMode);
   151→        var retval = new BlockProcessingResult(error);
   152→        handleFailedBlockProcessing(block, retval, shouldRecordBadBlock, context);
   153→        return retval;
   154→      }
   155→    } catch (StorageException ex) {
   156→      var retval = new BlockProcessingResult(Optional.empty(), ex);
   157→      // Blocks should not be marked bad due to a local storage failure
   158→      handleFailedBlockProcessing(block, retval, false, context);
   159→      return retval;
   160→    }
   161→
   162→    final WorldStateQueryParams worldStateQueryParams =
   163→        WorldStateQueryParams.newBuilder()
   164→            .withBlockHeader(parentHeader)
   165→            .withShouldWorldStateUpdateHead(shouldUpdateHead)
   166→            .build();
   167→    try (final var worldState =
   168→        context.getWorldStateArchive().getWorldState(worldStateQueryParams).orElse(null)) {
   169→
   170→      if (worldState == null) {
   171→        var retval =
   172→            new BlockProcessingResult(
   173→                "Unable to process block because parent world state "
   174→                    + parentHeader.getStateRoot()
   175→                    + " is not available");
   176→        // Blocks should not be marked bad due to missing data
   177→        handleFailedBlockProcessing(block, retval, false, context);
   178→        return retval;
   179→      }
   180→      var result = processBlock(context, worldState, block);
   181→      if (result.isFailed()) {
   182→        handleFailedBlockProcessing(block, result, shouldRecordBadBlock, context);
   183→        return result;
   184→      } else {
   185→        List<TransactionReceipt> receipts =
   186→            result.getYield().map(BlockProcessingOutputs::getReceipts).orElse(new ArrayList<>());
   187→        Optional<List<Request>> maybeRequests =
   188→            result.getYield().flatMap(BlockProcessingOutputs::getRequests);
   189→        Optional<BlockAccessList> blockAccessList =
   190→            result.getYield().flatMap(BlockProcessingOutputs::getBlockAccessList);
   191→        if (!blockBodyValidator.validateBody(
   192→            context,
   193→            block,
   194→            receipts,
   195→            worldState.rootHash(),
   196→            ommerValidationMode,
   197→            BodyValidationMode.FULL)) {
   198→          result = new BlockProcessingResult("failed to validate output of imported block");
   199→          handleFailedBlockProcessing(block, result, shouldRecordBadBlock, context);
   200→          return result;
   201→        }
   202→
   203→        return new BlockProcessingResult(
   204→            Optional.of(
   205→                new BlockProcessingOutputs(worldState, receipts, maybeRequests, blockAccessList)),
   206→            result.getNbParallelizedTransactions());
   207→      }
   208→    } catch (MerkleTrieException ex) {
   209→      context.getWorldStateArchive().heal(ex.getMaybeAddress(), ex.getLocation());
   210→      return new BlockProcessingResult(Optional.empty(), ex);
   211→    } catch (StorageException ex) {
   212→      var retval = new BlockProcessingResult(Optional.empty(), ex);
   213→      // Do not record bad block due to a local storage issue
   214→      handleFailedBlockProcessing(block, retval, false, context);
   215→      return retval;
   216→    } catch (Exception ex) {
   217→      // Wrap checked autocloseable exception from try-with-resources
   218→      throw new RuntimeException(ex);
   219→    }
   220→  }
   221→
   222→  /**
   223→   * Handles the processing of a block that has failed validation or processing.
   224→   *
   225→   * @param failedBlock the block that failed processing
   226→   * @param result the result of the block processing
   227→   * @param shouldRecordBadBlock whether to record the block as a bad block
   228→   * @param context the ProtocolContext
   229→   */
   230→  protected void handleFailedBlockProcessing(
   231→      final Block failedBlock,
   232→      final BlockValidationResult result,
   233→      final boolean shouldRecordBadBlock,
   234→      final ProtocolContext context) {
   235→    if (result.causedBy().isPresent()) {
   236→      // Block processing failed exceptionally, we cannot assume the block was intrinsically invalid
   237→      LOG.info(
   238→          "Failed to process block {}: {}, caused by {}",
