    34→public class MainnetBlockBodyValidator implements BlockBodyValidator {
    35→
    36→  private static final Logger LOG = LoggerFactory.getLogger(MainnetBlockBodyValidator.class);
    37→
    38→  private static final int MAX_OMMERS = 2;
    39→
    40→  private static final int MAX_GENERATION = 6;
    41→  protected final ProtocolSchedule protocolSchedule;
    42→
    43→  public MainnetBlockBodyValidator(final ProtocolSchedule protocolSchedule) {
    44→    this.protocolSchedule = protocolSchedule;
    45→  }
    46→
    47→  @Override
    48→  public boolean validateBody(
    49→      final ProtocolContext context,
    50→      final Block block,
    51→      final List<TransactionReceipt> receipts,
    52→      final Hash worldStateRootHash,
    53→      final HeaderValidationMode ommerValidationMode,
    54→      final BodyValidationMode bodyValidationMode) {
    55→    if (bodyValidationMode == BodyValidationMode.NONE) {
    56→      return true;
    57→    }
    58→
    59→    if (bodyValidationMode == BodyValidationMode.LIGHT
    60→        || bodyValidationMode == BodyValidationMode.FULL) {
    61→      if (!validateBodyLight(context, block, receipts, ommerValidationMode)) {
    62→        return false;
    63→      }
    64→    }
    65→
    66→    if (bodyValidationMode == BodyValidationMode.ROOT_ONLY
    67→        || bodyValidationMode == BodyValidationMode.FULL) {
    68→      return validateBodyRoots(block, receipts, worldStateRootHash);
    69→    }
    70→    return true;
    71→  }
    72→
    73→  @VisibleForTesting
    74→  protected boolean validateBodyRoots(
    75→      final Block block, final List<TransactionReceipt> receipts, final Hash worldStateRootHash) {
    76→    final BlockHeader header = block.getHeader();
    77→    final BlockBody body = block.getBody();
    78→
    79→    final Bytes32 transactionsRoot = BodyValidation.transactionsRoot(body.getTransactions());
    80→    if (!validateTransactionsRoot(header, header.getTransactionsRoot(), transactionsRoot)) {
    81→      return false;
    82→    }
    83→
    84→    final Bytes32 receiptsRoot = BodyValidation.receiptsRoot(receipts);
    85→    if (!validateReceiptsRoot(header, header.getReceiptsRoot(), receiptsRoot)) {
    86→      return false;
    87→    }
    88→
    89→    if (!validateStateRoot(
    90→        block.getHeader(), block.getHeader().getStateRoot(), worldStateRootHash)) {
    91→      LOG.warn("Invalid block RLP : {}", block.toRlp().toHexString());
    92→      receipts.forEach(
    93→          receipt ->
    94→              LOG.warn("Transaction receipt found in the invalid block {}", receipt.toString()));
    95→      return false;
    96→    }
    97→    return true;
    98→  }
    99→
   100→  @Override
   101→  public boolean validateBodyLight(
   102→      final ProtocolContext context,
   103→      final Block block,
   104→      final List<TransactionReceipt> receipts,
   105→      final HeaderValidationMode ommerValidationMode) {
   106→
   107→    final BlockHeader header = block.getHeader();
   108→
   109→    final long gasUsed =
   110→        receipts.isEmpty() ? 0 : receipts.get(receipts.size() - 1).getCumulativeGasUsed();
   111→    if (!validateGasUsed(header, header.getGasUsed(), gasUsed)) {
   112→      return false;
   113→    }
   114→
   115→    if (!validateLogsBloom(header, header.getLogsBloom(), BodyValidation.logsBloom(receipts))) {
   116→      return false;
   117→    }
   118→
   119→    if (!validateEthHash(context, block, ommerValidationMode)) {
   120→      return false;
   121→    }
   122→
   123→    if (!validateWithdrawals(block)) {
   124→      return false;
   125→    }
   126→    return true;
   127→  }
   128→
   129→  private boolean validateTransactionsRoot(
   130→      final BlockHeader header, final Bytes32 expected, final Bytes32 actual) {
   131→    if (!expected.equals(actual)) {
   132→      LOG.warn(
   133→          "Invalid block {}: transaction root mismatch (expected={}, actual={})",
   134→          header.toLogString(),
   135→          expected,
   136→          actual);
   137→      return false;
   138→    }
   139→
   140→    return true;
   141→  }
   142→
   143→  private static boolean validateLogsBloom(
   144→      final BlockHeader header, final LogsBloomFilter expected, final LogsBloomFilter actual) {
   145→    if (!expected.equals(actual)) {
   146→      LOG.warn(
   147→          "Invalid block {}: logs bloom filter mismatch (expected={}, actual={})",
   148→          header.toLogString(),
   149→          expected,
   150→          actual);
   151→      return false;
   152→    }
   153→
   154→    return true;
   155→  }
   156→
   157→  private static boolean validateGasUsed(
   158→      final BlockHeader header, final long expected, final long actual) {
   159→    if (expected != actual) {
   160→      LOG.warn(
   161→          "Invalid block {}: gas used mismatch (expected={}, actual={})",
   162→          header.toLogString(),
   163→          expected,
   164→          actual);
   165→      return false;
   166→    }
   167→
   168→    return true;
   169→  }
   170→
   171→  private boolean validateReceiptsRoot(
   172→      final BlockHeader header, final Bytes32 expected, final Bytes32 actual) {
   173→    if (!expected.equals(actual)) {
   174→      LOG.warn(
   175→          "Invalid block {}: receipts root mismatch (expected={}, actual={})",
   176→          header.toLogString(),
   177→          expected,
   178→          actual);
   179→      return false;
   180→    }
   181→
   182→    return true;
   183→  }
   184→
   185→  private boolean validateStateRoot(
   186→      final BlockHeader header, final Bytes32 expected, final Bytes32 actual) {
   187→    if (!expected.equals(actual)) {
   188→      LOG.warn(
   189→          "Invalid block {}: state root mismatch (expected={}, actual={})",
   190→          header.toLogString(),
   191→          expected,
   192→          actual);
   193→      return false;
   194→    }
   195→
   196→    return true;
   197→  }
   198→
   199→  private boolean validateEthHash(
   200→      final ProtocolContext context,
   201→      final Block block,
   202→      final HeaderValidationMode ommerValidationMode) {
   203→    final BlockHeader header = block.getHeader();
   204→    final BlockBody body = block.getBody();
   205→
   206→    final Bytes32 ommerHash = BodyValidation.ommersHash(body.getOmmers());
   207→    if (!validateOmmersHash(header, header.getOmmersHash(), ommerHash)) {
   208→      return false;
   209→    }
   210→
   211→    if (!validateOmmers(context, header, body.getOmmers(), ommerValidationMode)) {
   212→      return false;
   213→    }
   214→
   215→    return true;
   216→  }
   217→
   218→  private static boolean validateOmmersHash(
   219→      final BlockHeader header, final Bytes32 expected, final Bytes32 actual) {
   220→    if (!expected.equals(actual)) {
   221→      LOG.warn(
   222→          "Invalid block {}: ommers hash mismatch (expected={}, actual={})",
   223→          header.toLogString(),
   224→          expected,
   225→          actual);
   226→      return false;
   227→    }
   228→
   229→    return true;
   230→  }
   231→
   232→  private boolean validateOmmers(
   233→      final ProtocolContext context,
   234→      final BlockHeader header,
   235→      final List<BlockHeader> ommers,
   236→      final HeaderValidationMode ommerValidationMode) {
   237→    if (ommers.size() > MAX_OMMERS) {
   238→      LOG.warn(
   239→          "Invalid block {}: ommer count {} exceeds ommer limit {}",
   240→          header.toLogString(),
   241→          ommers.size(),
   242→          MAX_OMMERS);
   243→      return false;
   244→    }
   245→
   246→    if (!areOmmersUnique(ommers)) {
   247→      LOG.warn("Invalid block {}: ommers are not unique", header.toLogString());
   248→      return false;
   249→    }
   250→
   251→    for (final BlockHeader ommer : ommers) {
   252→      if (!isOmmerValid(context, header, ommer, ommerValidationMode)) {
   253→        LOG.warn("Invalid block {}: ommer is invalid", header.toLogString());
   254→        return false;
   255→      }
   256→    }
   257→
   258→    return true;
   259→  }
   260→
   261→  private static boolean areOmmersUnique(final List<BlockHeader> ommers) {
   262→    final Set<BlockHeader> uniqueOmmers = new HashSet<>(ommers);
   263→
   264→    return uniqueOmmers.size() == ommers.size();
   265→  }
   266→
   267→  private static boolean areSiblings(final BlockHeader a, final BlockHeader b) {
   268→    // Siblings cannot be the same.
   269→    if (a.equals(b)) {
   270→      return false;
   271→    }
   272→
   273→    return a.getParentHash().equals(b.getParentHash());
   274→  }
   275→
   276→  private boolean isOmmerValid(
   277→      final ProtocolContext context,
   278→      final BlockHeader current,
   279→      final BlockHeader ommer,
   280→      final HeaderValidationMode ommerValidationMode) {
   281→    final ProtocolSpec protocolSpec = protocolSchedule.getByBlockHeader(ommer);
   282→    if (!protocolSpec
   283→        .getOmmerHeaderValidator()
   284→        .validateHeader(ommer, context, ommerValidationMode)) {
   285→      return false;
   286→    }
   287→
   288→    if (!ommerValidationMode.isFormOfLightValidation()) {
   289→      return isOmmerSiblingOfAncestor(context, current, ommer);
   290→    } else {
   291→      return true;
   292→    }
   293→  }
   294→
   295→  private boolean isOmmerSiblingOfAncestor(
   296→      final ProtocolContext context, final BlockHeader current, final BlockHeader ommer) {
   297→    // The current block is guaranteed to have a parent because it's a valid header.
   298→    final long lastAncestorBlockNumber = Math.max(current.getNumber() - MAX_GENERATION, 0);
   299→
   300→    BlockHeader previous = current;
   301→    while (previous.getNumber() > lastAncestorBlockNumber) {
   302→      final BlockHeader ancestor =
   303→          context.getBlockchain().getBlockHeader(previous.getParentHash()).get();
   304→      if (areSiblings(ommer, ancestor)) {
   305→        return true;
   306→      }
   307→      previous = ancestor;
   308→    }
   309→    return false;
   310→  }
   311→
   312→  private boolean validateWithdrawals(final Block block) {
   313→    final WithdrawalsValidator withdrawalsValidator =
   314→        protocolSchedule.getByBlockHeader(block.getHeader()).getWithdrawalsValidator();
   315→
   316→    if (!withdrawalsValidator.validateWithdrawals(block.getBody().getWithdrawals())) {
   317→      return false;
   318→    }
   319→
   320→    if (!withdrawalsValidator.validateWithdrawalsRoot(block)) {
   321→      return false;
   322→    }
   323→
   324→    return true;
   325→  }
   326→}
