    29→public class DefaultNodeFactory<V> implements NodeFactory<V> {
    30→  @SuppressWarnings("rawtypes")
    31→  private static final Node NULL_NODE = NullNode.instance();
    32→
    33→  private static final int NB_CHILD = 16;
    34→
    35→  private final Function<V, Bytes> valueSerializer;
    36→
    37→  public DefaultNodeFactory(final Function<V, Bytes> valueSerializer) {
    38→    this.valueSerializer = valueSerializer;
    39→  }
    40→
    41→  @Override
    42→  public Node<V> createExtension(final Bytes path, final Node<V> child) {
    43→    return new ExtensionNode<>(path, child, this);
    44→  }
    45→
    46→  @SuppressWarnings("unchecked")
    47→  @Override
    48→  public Node<V> createBranch(
    49→      final byte leftIndex, final Node<V> left, final byte rightIndex, final Node<V> right) {
    50→    assert (leftIndex <= NB_CHILD);
    51→    assert (rightIndex <= NB_CHILD);
    52→    assert (leftIndex != rightIndex);
    53→
    54→    final ArrayList<Node<V>> children =
    55→        new ArrayList<>(Collections.nCopies(NB_CHILD, (Node<V>) NULL_NODE));
    56→    if (leftIndex == NB_CHILD) {
    57→      children.set(rightIndex, right);
    58→      return createBranch(children, left.getValue());
    59→    } else if (rightIndex == NB_CHILD) {
    60→      children.set(leftIndex, left);
    61→      return createBranch(children, right.getValue());
    62→    } else {
    63→      children.set(leftIndex, left);
    64→      children.set(rightIndex, right);
    65→      return createBranch(children, Optional.empty());
    66→    }
    67→  }
    68→
    69→  @Override
    70→  public Node<V> createBranch(final List<Node<V>> children, final Optional<V> value) {
    71→    return new BranchNode<>(children, value, this, valueSerializer);
    72→  }
    73→
    74→  @Override
    75→  public Node<V> createLeaf(final Bytes path, final V value) {
    76→    return new LeafNode<>(path, value, this, valueSerializer);
    77→  }
    78→}
