    27→/** An {@link RLPOutput} that writes RLP encoded data to a {@link Bytes}. */
    28→public class BytesValueRLPOutput implements RLPOutput {
    29→  /*
    30→   * The algorithm implemented works as follows:
    31→   *
    32→   * Values written to the output are accumulated in the 'values' list. When a list is started, it
    33→   * is indicated by adding a specific marker in that list (LIST_MARKER).
    34→   * While this is gathered, we also incrementally compute the size of the payload of every list of
    35→   * that output. Those sizes are stored in 'payloadSizes': when all the output has been added,
    36→   * payloadSizes[i] will contain the size of the (encoded) payload of the ith list in 'values'
    37→   * (that is, the list that starts at the ith LIST_MARKER in 'values').
    38→   *
    39→   * With that information gathered, encoded() can write its output in a single walk of 'values':
    40→   * values can be encoded directly, and every time we read a list marker, we use the corresponding
    41→   * payload size to write the proper prefix and continue.
    42→   *
    43→   * The main remaining aspect is how the values of 'payloadSizes' are computed. Computing the size
    44→   * of a list without nesting inside is easy: simply add the encoded size of any newly added value
    45→   * to the running size. The difficulty is with nesting: when we start a new list, we need to
    46→   * track both the sizes of the previous list and the new one. To deal with that, we use the small
    47→   * stack 'parentListStack': it stores the index in 'payloadSizes' of every currently "open" lists.
    48→   * In other words, payloadSizes[parentListStack[stackSize - 1]] corresponds to the size of the
    49→   * current list, the one to which newly added value are currently written (until the next call
    50→   * to 'endList()' that is, while payloadSizes[parentListStack[stackSize - 2]] would be the size
    51→   * of the parent list, ....
    52→   *
    53→   * Note that when a new value is added, we add its size only the currently running list. We should
    54→   * add that size to that of any parent list as well, but we do so indirectly when a list is
    55→   * finished: when 'endList()' is called, we add the size of the full list we just finished (and
    56→   * whose size we have now completed) to its parent size.
    57→   *
    58→   * Side-note: this class internally and informally use "element" to refer to a non list items.
    59→   */
    60→
    61→  private static final Bytes LIST_MARKER = Bytes.wrap(new byte[0]);
    62→
    63→  private final List<Bytes> values = new ArrayList<>();
    64→  // For every value i in values, rlpEncoded.get(i) will be true only if the value stored is an
    65→  // already encoded item.
    66→  private final BitSet rlpEncoded = new BitSet();
    67→
    68→  // First element is the total size of everything (the encoding may be a single non-list item, so
    69→  // this handles that case more easily; we need that value to size out final output). Following
    70→  // elements holds the size of the payload of the ith list in 'values'.
    71→  private int[] payloadSizes = new int[8];
    72→  private int listsCount = 1; // number of lists current in 'values' + 1.
    73→
    74→  private int[] parentListStack = new int[4];
    75→  private int stackSize = 1;
    76→
    77→  private int currentList() {
    78→    return parentListStack[stackSize - 1];
    79→  }
    80→
    81→  @Override
    82→  public void writeBytes(final Bytes v) {
    83→    checkState(
    84→        stackSize > 1 || values.isEmpty(), "Terminated RLP output, cannot add more elements");
    85→    values.add(v);
    86→    payloadSizes[currentList()] += RLPEncodingHelpers.elementSize(v);
    87→  }
    88→
    89→  @Override
    90→  public void writeRaw(final Bytes v) {
    91→    checkState(
    92→        stackSize > 1 || values.isEmpty(), "Terminated RLP output, cannot add more elements");
    93→    values.add(v);
    94→    // Mark that last value added as already encoded.
    95→    rlpEncoded.set(values.size() - 1);
    96→    payloadSizes[currentList()] += v.size();
    97→  }
    98→
    99→  @Override
   100→  public void startList() {
   101→    values.add(LIST_MARKER);
   102→    ++listsCount; // we'll add a new element to payloadSizes
   103→    ++stackSize; // and to the list stack.
   104→
   105→    // Resize our lists if necessary.
   106→    if (listsCount > payloadSizes.length) {
   107→      payloadSizes = Arrays.copyOf(payloadSizes, (payloadSizes.length * 3) / 2);
   108→    }
   109→    if (stackSize > parentListStack.length) {
   110→      parentListStack = Arrays.copyOf(parentListStack, (parentListStack.length * 3) / 2);
   111→    }
   112→
   113→    // The new current list size is store in the slot we just made room for by incrementing
   114→    // listsCount
   115→    parentListStack[stackSize - 1] = listsCount - 1;
   116→  }
   117→
   118→  @Override
   119→  public void endList() {
   120→    checkState(stackSize > 1, "LeaveList() called with no prior matching startList()");
   121→
   122→    final int current = currentList();
   123→    final int finishedListSize = RLPEncodingHelpers.listSize(payloadSizes[current]);
   124→    --stackSize;
   125→
   126→    // We just finished an item of our parent list, add it to that parent list size now.
   127→    final int newCurrent = currentList();
   128→    payloadSizes[newCurrent] += finishedListSize;
   129→  }
   130→
   131→  /**
   132→   * Computes the final encoded data size.
   133→   *
   134→   * @return The size of the RLP-encoded data written to this output.
   135→   * @throws IllegalStateException if some opened list haven't been closed (the output is not valid
   136→   *     as is).
   137→   */
   138→  public int encodedSize() {
   139→    checkState(stackSize == 1, "A list has been entered (startList()) but not left (endList())");
   140→    return payloadSizes[0];
   141→  }
   142→
   143→  /**
   144→   * Write the rlp encoded value to the provided {@link MutableBytes}
   145→   *
   146→   * @param mutableBytes the value to which the rlp-data will be written
   147→   */
