    69→   * @param extensionNode The extension node being visited.
    70→   */
    71→  @Override
    72→  public void visit(final Bytes location, final ExtensionNode<V> extensionNode) {
    73→    if (!extensionNode.isDirty()) {
    74→      return;
    75→    }
    76→
    77→    final Node<V> child = extensionNode.getChild();
    78→    if (child.isDirty()) {
    79→      child.accept(Bytes.concatenate(location, extensionNode.getPath()), this);
    80→    }
    81→    if (child.isHealNeeded()
    82→        || !isInRange(
