    42→/**
    43→ * Validates a transaction based on Frontier protocol runtime requirements.
    44→ *
    45→ * <p>The {@link MainnetTransactionValidator} performs the intrinsic gas cost check on the given
    46→ * {@link Transaction}.
    47→ */
    48→public class MainnetTransactionValidator implements TransactionValidator {
    49→  private static final Logger LOG = LoggerFactory.getLogger(MainnetTransactionValidator.class);
    50→
    51→  public static final BigInteger TWO_POW_256 = BigInteger.TWO.pow(256);
    52→
    53→  private final GasCalculator gasCalculator;
    54→  private final GasLimitCalculator gasLimitCalculator;
    55→  private final FeeMarket feeMarket;
    56→
    57→  private final boolean disallowSignatureMalleability;
    58→
    59→  private final Optional<BigInteger> chainId;
    60→
    61→  private final Set<TransactionType> acceptedTransactionTypes;
    62→
    63→  private final int maxInitcodeSize;
    64→  private final MainnetBlobsValidator blobsValidator;
    65→
    66→  public MainnetTransactionValidator(
    67→      final GasCalculator gasCalculator,
    68→      final GasLimitCalculator gasLimitCalculator,
    69→      final FeeMarket feeMarket,
    70→      final boolean checkSignatureMalleability,
    71→      final Optional<BigInteger> chainId,
    72→      final Set<TransactionType> acceptedTransactionTypes,
    73→      final Set<BlobType> acceptedBlobVersions,
    74→      final int maxInitcodeSize) {
    75→    this.gasCalculator = gasCalculator;
    76→    this.gasLimitCalculator = gasLimitCalculator;
    77→    this.feeMarket = feeMarket;
    78→    this.disallowSignatureMalleability = checkSignatureMalleability;
    79→    this.chainId = chainId;
    80→    this.acceptedTransactionTypes = acceptedTransactionTypes;
    81→    this.maxInitcodeSize = maxInitcodeSize;
    82→    this.blobsValidator =
    83→        new MainnetBlobsValidator(acceptedBlobVersions, gasLimitCalculator, gasCalculator);
    84→  }
    85→
    86→  @Override
    87→  public ValidationResult<TransactionInvalidReason> validate(
    88→      final Transaction transaction,
    89→      final Optional<Wei> baseFee,
    90→      final Optional<Wei> blobFee,
    91→      final TransactionValidationParams transactionValidationParams) {
    92→    final ValidationResult<TransactionInvalidReason> signatureResult =
    93→        validateTransactionSignature(transaction);
    94→    if (!signatureResult.isValid()) {
    95→      return signatureResult;
    96→    }
    97→
    98→    final TransactionType transactionType = transaction.getType();
    99→    if (!acceptedTransactionTypes.contains(transactionType)) {
   100→      return ValidationResult.invalid(
   101→          TransactionInvalidReason.INVALID_TRANSACTION_FORMAT,
   102→          String.format(
   103→              "Transaction type %s is invalid, accepted transaction types are %s",
   104→              transactionType, acceptedTransactionTypes));
   105→    }
   106→
   107→    if (transaction.getNonce() == MAX_NONCE) {
   108→      return ValidationResult.invalid(
   109→          TransactionInvalidReason.NONCE_OVERFLOW, "Nonce must be less than 2^64-1");
   110→    }
   111→
   112→    if (!transactionValidationParams.isAllowExceedingGasLimit()
   113→        && transaction.getGasLimit() > gasLimitCalculator.transactionGasLimitCap()) {
   114→      return ValidationResult.invalid(
   115→          TransactionInvalidReason.EXCEEDS_TRANSACTION_GAS_LIMIT,
   116→          "Transaction gas limit must be at most " + gasLimitCalculator.transactionGasLimitCap());
   117→    }
   118→
   119→    if (transactionType.supportsBlob()) {
   120→      final ValidationResult<TransactionInvalidReason> blobTransactionResult =
   121→          blobsValidator.validate(transaction);
   122→      if (!blobTransactionResult.isValid()) {
   123→        LOG.info(
   124→            "Blob transaction {} validation failed: {}",
   125→            transaction.getHash().toHexString(),
   126→            blobTransactionResult.getErrorMessage());
   127→        return blobTransactionResult;
   128→      }
   129→    }
   130→
   131→    if (transaction.isContractCreation() && transaction.getPayload().size() > maxInitcodeSize) {
   132→      return ValidationResult.invalid(
   133→          TransactionInvalidReason.INITCODE_TOO_LARGE,
   134→          String.format(
   135→              "Initcode size of %d exceeds maximum size of %s",
   136→              transaction.getPayload().size(), maxInitcodeSize));
   137→    }
   138→
   139→    if (transactionType == TransactionType.DELEGATE_CODE) {
   140→      ValidationResult<TransactionInvalidReason> codeDelegationValidation =
   141→          validateCodeDelegation(transaction);
   142→      if (!codeDelegationValidation.isValid()) {
   143→        return codeDelegationValidation;
   144→      }
   145→    }
   146→
   147→    return validateCostAndFee(transaction, baseFee, blobFee, transactionValidationParams);
   148→  }
   149→
   150→  private static ValidationResult<TransactionInvalidReason> validateCodeDelegation(
   151→      final Transaction transaction) {
   152→    if (isDelegateCodeEmpty(transaction)) {
   153→      return ValidationResult.invalid(
   154→          TransactionInvalidReason.EMPTY_CODE_DELEGATION,
   155→          "transaction code delegation transactions must have a non-empty code delegation list");
   156→    }
   157→
   158→    if (transaction.getTo().isEmpty()) {
   159→      return ValidationResult.invalid(
   160→          TransactionInvalidReason.INVALID_TRANSACTION_FORMAT,
   161→          "transaction code delegation transactions must have a to address");
   162→    }
   163→
   164→    final Optional<ValidationResult<TransactionInvalidReason>> validationResult =
   165→        transaction
   166→            .getCodeDelegationList()
   167→            .map(
   168→                codeDelegations -> {
   169→                  for (CodeDelegation codeDelegation : codeDelegations) {
   170→                    if (codeDelegation.chainId().compareTo(TWO_POW_256) >= 0) {
   171→                      throw new IllegalArgumentException(
   172→                          "Invalid 'chainId' value, should be < 2^256 but got "
   173→                              + codeDelegation.chainId());
   174→                    }
   175→
   176→                    if (codeDelegation.r().compareTo(TWO_POW_256) >= 0) {
   177→                      throw new IllegalArgumentException(
   178→                          "Invalid 'r' value, should be < 2^256 but got " + codeDelegation.r());
   179→                    }
   180→
   181→                    if (codeDelegation.s().compareTo(TWO_POW_256) >= 0) {
   182→                      throw new IllegalArgumentException(
   183→                          "Invalid 's' value, should be < 2^256 but got " + codeDelegation.s());
   184→                    }
   185→                  }
   186→
   187→                  return ValidationResult.valid();
   188→                });
   189→
   190→    if (validationResult.isPresent() && !validationResult.get().isValid()) {
   191→      return validationResult.get();
   192→    }
   193→
   194→    return ValidationResult.valid();
   195→  }
   196→
   197→  private static boolean isDelegateCodeEmpty(final Transaction transaction) {
   198→    return transaction.getCodeDelegationList().isEmpty()
   199→        || transaction.getCodeDelegationList().get().isEmpty();
   200→  }
   201→
   202→  private ValidationResult<TransactionInvalidReason> validateCostAndFee(
   203→      final Transaction transaction,
   204→      final Optional<Wei> maybeBaseFee,
   205→      final Optional<Wei> maybeBlobFee,
   206→      final TransactionValidationParams transactionValidationParams) {
   207→
   208→    if (maybeBaseFee.isPresent()) {
   209→      final Wei price = feeMarket.getTransactionPriceCalculator().price(transaction, maybeBaseFee);
   210→      if (!transactionValidationParams.allowUnderpriced()
   211→          && price.compareTo(maybeBaseFee.orElseThrow()) < 0) {
   212→        return ValidationResult.invalid(
   213→            TransactionInvalidReason.GAS_PRICE_BELOW_CURRENT_BASE_FEE,
   214→            "gasPrice is less than the current BaseFee");
   215→      }
   216→
   217→      // assert transaction.max_fee_per_gas >= transaction.max_priority_fee_per_gas
   218→      if (transaction.getType().supports1559FeeMarket()
   219→          && transaction
   220→                  .getMaxPriorityFeePerGas()
   221→                  .get()
   222→                  .getAsBigInteger()
   223→                  .compareTo(transaction.getMaxFeePerGas().get().getAsBigInteger())
   224→              > 0) {
   225→        return ValidationResult.invalid(
   226→            TransactionInvalidReason.MAX_PRIORITY_FEE_PER_GAS_EXCEEDS_MAX_FEE_PER_GAS,
   227→            "max priority fee per gas cannot be greater than max fee per gas");
   228→      }
   229→    }
   230→
   231→    if (transaction.getType().supportsBlob()) {
   232→      final long txTotalBlobGas = gasCalculator.blobGasCost(transaction.getBlobCount());
   233→      if (txTotalBlobGas > gasLimitCalculator.currentBlobGasLimit()) {
   234→        return ValidationResult.invalid(
   235→            TransactionInvalidReason.TOTAL_BLOB_GAS_TOO_HIGH,
   236→            String.format(
   237→                "total blob gas %d exceeds max blob gas per block %d",
   238→                txTotalBlobGas, gasLimitCalculator.currentBlobGasLimit()));
   239→      }
   240→      if (maybeBlobFee.isEmpty()) {
   241→        throw new IllegalArgumentException(
   242→            "blob fee must be provided from blocks containing blobs");
   243→        // tx.getMaxFeePerBlobGas can be empty for eth_call
   244→      } else if (!transactionValidationParams.allowUnderpriced()
   245→          && maybeBlobFee.get().compareTo(transaction.getMaxFeePerBlobGas().get()) > 0) {
   246→        return ValidationResult.invalid(
   247→            TransactionInvalidReason.BLOB_GAS_PRICE_BELOW_CURRENT_BLOB_BASE_FEE,
   248→            String.format(
   249→                "tx max fee per blob gas less than block blob gas fee: address %s blobGasFeeCap: %s, blobBaseFee: %s",
   250→                transaction.getSender().toHexString(),
   251→                transaction.getMaxFeePerBlobGas().get().toHumanReadableString(),
   252→                maybeBlobFee.get().toHumanReadableString()));
   253→      }
   254→    }
   255→
   256→    final long baselineGas =
   257→        clampedAdd(
   258→            transaction.getAccessList().map(gasCalculator::accessListGasCost).orElse(0L),
   259→            gasCalculator.delegateCodeGasCost(transaction.codeDelegationListSize()));
   260→    final long intrinsicGasCostOrFloor =
   261→        Math.max(
   262→            gasCalculator.transactionIntrinsicGasCost(transaction, baselineGas),
   263→            gasCalculator.transactionFloorCost(
   264→                transaction.getPayload(), transaction.getPayloadZeroBytes()));
   265→
   266→    if (Long.compareUnsigned(intrinsicGasCostOrFloor, transaction.getGasLimit()) > 0) {
   267→      return ValidationResult.invalid(
   268→          TransactionInvalidReason.INTRINSIC_GAS_EXCEEDS_GAS_LIMIT,
   269→          String.format(
   270→              "intrinsic gas cost %s exceeds gas limit %s",
   271→              intrinsicGasCostOrFloor, transaction.getGasLimit()));
   272→    }
   273→
   274→    if (transaction.calculateUpfrontGasCost(transaction.getMaxGasPrice(), Wei.ZERO, 0).bitLength()
   275→        > 256) {
   276→      return ValidationResult.invalid(
   277→          TransactionInvalidReason.UPFRONT_COST_EXCEEDS_UINT256,
   278→          "Upfront gas cost cannot exceed 2^256 Wei");
   279→    }
   280→
   281→    return ValidationResult.valid();
   282→  }
