   284→  @Override
   285→  public ValidationResult<TransactionInvalidReason> validateForSender(
   286→      final Transaction transaction,
   287→      final Account sender,
   288→      final TransactionValidationParams validationParams) {
   289→    Wei senderBalance = Account.DEFAULT_BALANCE;
   290→    long senderNonce = Account.DEFAULT_NONCE;
   291→    Hash codeHash = Hash.EMPTY;
   292→
   293→    if (sender != null) {
   294→      senderBalance = sender.getBalance();
   295→      senderNonce = sender.getNonce();
   296→      if (sender.getCodeHash() != null) codeHash = sender.getCodeHash();
   297→    }
   298→
   299→    final Wei upfrontCost =
   300→        transaction.getUpfrontCost(gasCalculator.blobGasCost(transaction.getBlobCount()));
   301→    if (upfrontCost.compareTo(senderBalance) > 0) {
   302→      return ValidationResult.invalid(
   303→          TransactionInvalidReason.UPFRONT_COST_EXCEEDS_BALANCE,
   304→          String.format(
   305→              "transaction up-front cost %s exceeds transaction sender account balance %s",
   306→              upfrontCost.toQuantityHexString(), senderBalance.toQuantityHexString()));
   307→    }
   308→
   309→    if (Long.compareUnsigned(transaction.getNonce(), senderNonce) < 0) {
   310→      return ValidationResult.invalid(
   311→          TransactionInvalidReason.NONCE_TOO_LOW,
   312→          String.format(
   313→              "transaction nonce %s below sender account nonce %s",
   314→              transaction.getNonce(), senderNonce));
   315→    }
   316→
   317→    if (!validationParams.isAllowFutureNonce() && senderNonce != transaction.getNonce()) {
   318→      return ValidationResult.invalid(
   319→          TransactionInvalidReason.NONCE_TOO_HIGH,
   320→          String.format(
   321→              "transaction nonce %s does not match sender account nonce %s.",
   322→              transaction.getNonce(), senderNonce));
   323→    }
   324→
   325→    if (!validationParams.isAllowContractAddressAsSender()
   326→        && !canSendTransaction(sender, codeHash)) {
   327→      return ValidationResult.invalid(
   328→          TransactionInvalidReason.TX_SENDER_NOT_AUTHORIZED,
   329→          String.format(
   330→              "Sender %s has deployed code and so is not authorized to send transactions",
   331→              transaction.getSender()));
   332→    }
   333→
   334→    return ValidationResult.valid();
   335→  }
   336→
   337→  private static boolean canSendTransaction(final Account sender, final Hash codeHash) {
   338→    return codeHash.equals(Hash.EMPTY) || hasCodeDelegation(sender.getCode());
   339→  }
   340→
   341→  private ValidationResult<TransactionInvalidReason> validateTransactionSignature(
   342→      final Transaction transaction) {
   343→    if (chainId.isPresent()
   344→        && (transaction.getChainId().isPresent() && !transaction.getChainId().equals(chainId))) {
   345→      return ValidationResult.invalid(
   346→          TransactionInvalidReason.WRONG_CHAIN_ID,
   347→          String.format(
   348→              "transaction was meant for chain id %s and not this chain id %s",
   349→              transaction.getChainId().get(), chainId.get()));
   350→    }
   351→
   352→    if (chainId.isEmpty() && transaction.getChainId().isPresent()) {
   353→      return ValidationResult.invalid(
   354→          TransactionInvalidReason.REPLAY_PROTECTED_SIGNATURES_NOT_SUPPORTED,
   355→          "replay protected signatures is not supported");
   356→    }
   357→
   358→    final SECPSignature signature = transaction.getSignature();
   359→    final BigInteger halfCurveOrder = SignatureAlgorithmFactory.getInstance().getHalfCurveOrder();
   360→    if (disallowSignatureMalleability && signature.getS().compareTo(halfCurveOrder) > 0) {
   361→      return ValidationResult.invalid(
   362→          TransactionInvalidReason.INVALID_SIGNATURE,
   363→          String.format(
   364→              "Signature s value should be less than %s, but got %s",
   365→              halfCurveOrder, signature.getS()));
   366→    }
   367→
   368→    // org.bouncycastle.math.ec.ECCurve.AbstractFp.decompressPoint throws an
   369→    // IllegalArgumentException for "Invalid point compression" for bad signatures.
   370→    try {
   371→      transaction.getSender();
   372→    } catch (final IllegalArgumentException e) {
   373→      return ValidationResult.invalid(
   374→          TransactionInvalidReason.INVALID_SIGNATURE,
   375→          "sender could not be extracted from transaction signature");
   376→    }
   377→    return ValidationResult.valid();
   378→  }
   379→}
