    17→/** The GasLimitCalculator interface defines methods for calculating the gas limit. */
    18→public interface GasLimitCalculator {
    19→
    20→  /**
    21→   * The constant BLOB_GAS_LIMIT represents the gas limit for blob data. Defaults to the Cancun
    22→   * value where it was first introduced as part of EIP-4844
    23→   */
    24→  long BLOB_GAS_LIMIT = 0xC0000;
    25→
    26→  /**
    27→   * Calculates the next gas limit based on the current gas limit, target gas limit, and new block
    28→   * number.
    29→   *
    30→   * @param currentGasLimit the current gas limit
    31→   * @param targetGasLimit the target gas limit
    32→   * @param newBlockNumber the new block number
    33→   * @return the calculated next gas limit
    34→   */
    35→  long nextGasLimit(long currentGasLimit, long targetGasLimit, long newBlockNumber);
    36→
    37→  /**
    38→   * Returns a GasLimitCalculator that always returns the current gas limit.
    39→   *
    40→   * @return a GasLimitCalculator that always returns the current gas limit
    41→   */
    42→  static GasLimitCalculator constant() {
    43→    return (currentGasLimit, targetGasLimit, newBlockNumber) -> currentGasLimit;
    44→  }
    45→
    46→  /**
    47→   * Returns the current blob gas limit.
    48→   *
    49→   * @return the current blob gas limit
    50→   */
    51→  default long currentBlobGasLimit() {
    52→    return BLOB_GAS_LIMIT;
    53→  }
    54→
    55→  /**
    56→   * Retrieves the target blob gas per block. Added in Cancun.
    57→   *
    58→   * @return The target blob gas per block.
    59→   */
    60→  default long getTargetBlobGasPerBlock() {
    61→    return 0L;
    62→  }
    63→
    64→  /**
    65→   * Compute the new value for the excess blob gas, given the parent value and the blob gas used
    66→   *
    67→   * @param parentExcessBlobGas excess blob gas from the parent
    68→   * @param blobGasUsed blob gas used
    69→   * @param parentBaseFeePerGas base fee per gas from the parent
    70→   * @return the new excess blob gas value
    71→   */
    72→  default long computeExcessBlobGas(
    73→      final long parentExcessBlobGas, final long blobGasUsed, final long parentBaseFeePerGas) {
    74→    return 0L;
    75→  }
    76→
    77→  /**
    78→   * Return the transaction gas limit cap.
    79→   *
    80→   * <p>Before Osaka, there was no limit, and it is safe to use long max value to represent that,
    81→   * since no transaction has ever reached it.
    82→   *
    83→   * @return the transaction gas limit cap.
    84→   */
    85→  default long transactionGasLimitCap() {
    86→    return Long.MAX_VALUE;
    87→  }
    88→
    89→  /**
    90→   * Returns the transaction blob gas limit cap.
    91→   *
    92→   * <p>Before Osaka, there was no limit, the max number of blobs a transaction could have was
    93→   * limited by the blob gas limit.
    94→   *
    95→   * @return the transaction blob gas limit cap
    96→   */
    97→  default long transactionBlobGasLimitCap() {
    98→    return BLOB_GAS_LIMIT;
    99→  }
   100→}
