    26→public class OsakaTargetingGasLimitCalculator extends CancunTargetingGasLimitCalculator {
    27→  /** The constant max number of blobs per transaction defined for Osaka */
    28→  private static final int DEFAULT_MAX_BLOBS_PER_TRANSACTION = 6;
    29→
    30→  /** The blob base cost constant for Osaka */
    31→  private static final long BLOB_BASE_COST = 1 << 13; // 2^13
    32→
    33→  /** The mainnet transaction gas limit cap for Osaka */
    34→  private static final long DEFAULT_TRANSACTION_GAS_LIMIT_CAP_OSAKA = 16_777_216L;
    35→
    36→  private final long transactionGasLimitCap;
    37→  private final long transactionBlobGasLimitCap;
    38→
    39→  public OsakaTargetingGasLimitCalculator(
    40→      final long londonForkBlock,
    41→      final BaseFeeMarket feeMarket,
    42→      final GasCalculator gasCalculator,
    43→      final int maxBlobsPerBlock,
    44→      final int targetBlobsPerBlock) {
    45→    this(
    46→        londonForkBlock,
    47→        feeMarket,
    48→        gasCalculator,
    49→        maxBlobsPerBlock,
    50→        targetBlobsPerBlock,
    51→        DEFAULT_MAX_BLOBS_PER_TRANSACTION,
    52→        DEFAULT_TRANSACTION_GAS_LIMIT_CAP_OSAKA);
    53→  }
    54→
    55→  public OsakaTargetingGasLimitCalculator(
    56→      final long londonForkBlock,
    57→      final BaseFeeMarket feeMarket,
    58→      final GasCalculator gasCalculator,
    59→      final int maxBlobsPerBlock,
    60→      final int targetBlobsPerBlock,
    61→      final int maxBlobsPerTransaction,
    62→      final long transactionGasLimitCap) {
    63→    super(londonForkBlock, feeMarket, gasCalculator, maxBlobsPerBlock, targetBlobsPerBlock);
    64→    this.transactionGasLimitCap = transactionGasLimitCap;
    65→    this.transactionBlobGasLimitCap = gasCalculator.getBlobGasPerBlob() * maxBlobsPerTransaction;
    66→    checkArgument(
    67→        maxBlobsPerBlock >= maxBlobsPerTransaction,
    68→        "maxBlobsPerTransaction (%s) must not be greater than maxBlobsPerBlock (%s)",
    69→        maxBlobsPerTransaction,
    70→        maxBlobsPerBlock);
    71→  }
    72→
    73→  @Override
    74→  public long transactionGasLimitCap() {
    75→    return transactionGasLimitCap;
    76→  }
    77→
    78→  @Override
    79→  public long computeExcessBlobGas(
    80→      final long parentExcessBlobGas,
    81→      final long parentBlobGasUsed,
    82→      final long parentBaseFeePerGas) {
    83→    final long currentExcessBlobGas = parentExcessBlobGas + parentBlobGasUsed;
    84→
    85→    // First check if we're below the target
    86→    if (currentExcessBlobGas < getTargetBlobGasPerBlock()) {
    87→      return 0L;
    88→    }
    89→
    90→    // EIP-7918 https://eips.ethereum.org/EIPS/eip-7918
    91→    Wei blobGasBaseFee = feeMarket.blobGasPricePerGas(BlobGas.of(parentExcessBlobGas));
    92→
    93→    UInt256 parentBaseFee = UInt256.valueOf(parentBaseFeePerGas);
    94→    UInt256 blobGasPerBlob = UInt256.valueOf(getBlobGasPerBlob());
    95→
    96→    UInt256 baseFeeCostPerBlob = parentBaseFee.multiply(UInt256.valueOf(BLOB_BASE_COST));
    97→    UInt256 effectiveBlobGasCost = blobGasBaseFee.toUInt256().multiply(blobGasPerBlob);
    98→
    99→    if (baseFeeCostPerBlob.compareTo(effectiveBlobGasCost) > 0) {
   100→      return parentExcessBlobGas
   101→          + parentBlobGasUsed * (maxBlobsPerBlock - targetBlobsPerBlock) / maxBlobsPerBlock;
   102→    } else {
   103→      // same as Cancun
   104→      return currentExcessBlobGas - getTargetBlobGasPerBlock();
   105→    }
   106→  }
   107→
   108→  @Override
   109→  public long transactionBlobGasLimitCap() {
   110→    return transactionBlobGasLimitCap;
   111→  }
   112→}
