    29→public class RestoreVisitor<V> implements PathNodeVisitor<V> {
    30→
    31→  private final NodeFactory<V> nodeFactory;
    32→  private final V value;
    33→  private final NodeVisitor<V> persistVisitor;
    34→
    35→  public RestoreVisitor(
    36→      final Function<V, Bytes> valueSerializer,
    37→      final V value,
    38→      final NodeVisitor<V> persistVisitor) {
    39→    this.nodeFactory = new DefaultNodeFactory<>(valueSerializer);
    40→    this.value = value;
    41→    this.persistVisitor = persistVisitor;
    42→  }
    43→
    44→  @Override
    45→  public Node<V> visit(final ExtensionNode<V> extensionNode, final Bytes path) {
    46→    final Bytes extensionPath = extensionNode.getPath();
    47→
    48→    final int commonPathLength = extensionPath.commonPrefixLength(path);
    49→    assert commonPathLength < path.size()
    50→        : "Visiting path doesn't end with a non-matching terminator";
    51→
    52→    if (commonPathLength == extensionPath.size()) {
    53→      final Node<V> newChild = extensionNode.getChild().accept(this, path.slice(commonPathLength));
    54→      return extensionNode.replaceChild(newChild);
    55→    }
    56→
    57→    // path diverges before the end of the extension - create a new branch
    58→
    59→    final byte leafIndex = path.get(commonPathLength);
    60→    final Bytes leafPath = path.slice(commonPathLength + 1);
    61→
    62→    final byte extensionIndex = extensionPath.get(commonPathLength);
    63→    final Node<V> updatedExtension =
    64→        extensionNode.replacePath(extensionPath.slice(commonPathLength + 1));
    65→    final Node<V> leaf = nodeFactory.createLeaf(leafPath, value);
    66→    final Node<V> branch =
    67→        nodeFactory.createBranch(leafIndex, leaf, extensionIndex, updatedExtension);
    68→
    69→    if (commonPathLength > 0) {
    70→      return nodeFactory.createExtension(extensionPath.slice(0, commonPathLength), branch);
    71→    } else {
    72→      return branch;
    73→    }
    74→  }
    75→
    76→  @Override
    77→  public Node<V> visit(final BranchNode<V> branchNode, final Bytes path) {
    78→    assert path.size() > 0 : "Visiting path doesn't end with a non-matching terminator";
    79→    BranchNode<V> workingNode = branchNode;
    80→
    81→    final byte childIndex = path.get(0);
    82→    if (childIndex == CompactEncoding.LEAF_TERMINATOR) {
    83→      return workingNode.replaceValue(value);
    84→    }
    85→
    86→    for (byte i = 0; i < childIndex; i++) {
    87→      workingNode = persistNode(workingNode, i);
    88→    }
    89→
    90→    final Node<V> updatedChild = workingNode.child(childIndex).accept(this, path.slice(1));
    91→    return workingNode.replaceChild(childIndex, updatedChild);
    92→  }
    93→
    94→  private BranchNode<V> persistNode(final BranchNode<V> parent, final byte index) {
    95→    final Node<V> child = parent.getChildren().get(index);
    96→    if (!(child instanceof StoredNode)) {
    97→      child.accept(persistVisitor);
    98→      final PersistedNode<V> persistedNode =
    99→          new PersistedNode<>(null, child.getHash(), child.getEncodedBytesRef());
   100→      return (BranchNode<V>) parent.replaceChild(index, persistedNode);
   101→    } else {
   102→      return parent;
   103→    }
   104→  }
   105→
   106→  @Override
   107→  public Node<V> visit(final LeafNode<V> leafNode, final Bytes path) {
   108→    final Bytes leafPath = leafNode.getPath();
   109→    final int commonPathLength = leafPath.commonPrefixLength(path);
   110→
   111→    // Check if the current leaf node should be replaced
   112→    if (commonPathLength == leafPath.size() && commonPathLength == path.size()) {
   113→      return nodeFactory.createLeaf(leafPath, value);
   114→    }
   115→
   116→    assert commonPathLength < leafPath.size() && commonPathLength < path.size()
   117→        : "Should not have consumed non-matching terminator";
   118→
   119→    // The current leaf path must be split to accommodate the new value.
   120→
   121→    final byte newLeafIndex = path.get(commonPathLength);
   122→    final Bytes newLeafPath = path.slice(commonPathLength + 1);
   123→
   124→    final byte updatedLeafIndex = leafPath.get(commonPathLength);
   125→
   126→    final Node<V> updatedLeaf = leafNode.replacePath(leafPath.slice(commonPathLength + 1));
   127→    final Node<V> leaf = nodeFactory.createLeaf(newLeafPath, value);
   128→    final Node<V> branch =
   129→        nodeFactory.createBranch(updatedLeafIndex, updatedLeaf, newLeafIndex, leaf);
   130→    if (commonPathLength > 0) {
   131→      return nodeFactory.createExtension(leafPath.slice(0, commonPathLength), branch);
   132→    } else {
   133→      return branch;
   134→    }
   135→  }
   136→
   137→  @Override
   138→  public Node<V> visit(final NullNode<V> nullNode, final Bytes path) {
   139→    return nodeFactory.createLeaf(path, value);
   140→  }
   141→
   142→  static class PersistedNode<V> implements Node<V> {
   143→    private final Bytes path;
   144→    private final Bytes32 hash;
   145→    private final Bytes refRlp;
   146→
   147→    PersistedNode(final Bytes path, final Bytes32 hash, final Bytes refRlp) {
   148→      this.path = path;
   149→      this.hash = hash;
   150→      this.refRlp = refRlp;
   151→    }
   152→
   153→    /**
   154→     * @return True if the node needs to be persisted.
   155→     */
   156→    @Override
   157→    public boolean isDirty() {
   158→      return false;
   159→    }
   160→
   161→    /** Marks the node as being modified (needs to be persisted); */
   162→    @Override
   163→    public void markDirty() {
   164→      throw new UnsupportedOperationException(
   165→          "A persisted node cannot ever be dirty since it's loaded from storage");
   166→    }
   167→
   168→    @Override
   169→    public boolean isHealNeeded() {
   170→      return false;
   171→    }
   172→
   173→    @Override
   174→    public void markHealNeeded() {
   175→      throw new UnsupportedOperationException(
   176→          "A persisted node cannot be healed since it's loaded from storage");
   177→    }
   178→
   179→    @Override
   180→    public Node<V> accept(final PathNodeVisitor<V> visitor, final Bytes path) {
   181→      // do nothing
   182→      return this;
   183→    }
   184→
   185→    @Override
   186→    public void accept(final NodeVisitor<V> visitor) {
   187→      // do nothing
   188→    }
   189→
   190→    @Override
   191→    public void accept(final Bytes location, final LocationNodeVisitor<V> visitor) {
   192→      // do nothing
   193→    }
   194→
   195→    @Override
   196→    public Bytes getPath() {
   197→      return path;
   198→    }
   199→
   200→    @Override
   201→    public Optional<V> getValue() {
   202→      throw new UnsupportedOperationException(
   203→          "A persisted node cannot have a value, as it's already been restored.");
   204→    }
   205→
   206→    @Override
   207→    public List<Node<V>> getChildren() {
   208→      return List.of();
   209→    }
   210→
   211→    @Override
   212→    public Bytes getEncodedBytes() {
   213→      throw new UnsupportedOperationException(
   214→          "A persisted node cannot have rlp, as it's already been restored.");
   215→    }
   216→
   217→    @Override
   218→    public Bytes getEncodedBytesRef() {
   219→      return refRlp;
   220→    }
   221→
   222→    @Override
   223→    public boolean isReferencedByHash() {
   224→      // Persisted nodes represent only nodes that are referenced by hash
   225→      return true;
   226→    }
   227→
   228→    @Override
   229→    public Bytes32 getHash() {
   230→      return hash;
   231→    }
   232→
   233→    @Override
   234→    public Node<V> replacePath(final Bytes path) {
   235→      throw new UnsupportedOperationException(
   236→          "A persisted node cannot be replaced, as it's already been restored.");
   237→    }
   238→
   239→    @Override
   240→    public void unload() {
   241→      throw new UnsupportedOperationException(
   242→          "A persisted node cannot be unloaded, as it's already been restored.");
   243→    }
   244→
   245→    @Override
   246→    public String print() {
   247→      return "PersistedNode:" + "\n\tPath: " + getPath() + "\n\tHash: " + getHash();
   248→    }
   249→  }
   250→}
